        row_default = [field.converter.default for field in self.fields]
        mask_default = [True] * len(self.fields)
        array_chunk = []
        mask_chunk = []
        chunk_size = config.get("chunk_size", DEFAULT_CHUNK_SIZE)
        for start, tag, data, pos in iterator:
            if tag == "TR":
                # Now parse one row
                row = row_default[:]
                row_mask = mask_default[:]
                i = 0  # index of the column being read from disk
                j = 0  # index of the column being written in array (not necessarily == i)
                for start, tag, data, pos in iterator:
                    if start:
                        binary = data.get("encoding", None) == "base64"
                        warn_unknown_attrs(tag, data.keys(), config, pos, ["encoding"])
                    else:
                        if tag == "TD":
                            if i >= len(fields):
                                vo_raise(E20, len(fields), config, pos)

                            if colnumbers_bits[i]:
                                try:
                                    if binary:
                                        rawdata = base64.b64decode(data.encode("ascii"))
                                        buf = io.BytesIO(rawdata)
                                        buf.seek(0)
                                        try:
                                            value, mask_value = binparsers[i](buf.read)
                                        except Exception as e:
                                            vo_reraise(
                                                e,
                                                config,
                                                pos,
                                                (
                                                    f"(in row {len(array_chunk):d}, "
                                                    f"col '{fields[i].ID}')"
                                                ),
                                            )
                                    else:
                                        try:
                                            value, mask_value = parsers[i](
                                                data, config, pos
                                            )
                                        except Exception as e:
                                            vo_reraise(
                                                e,
                                                config,
                                                pos,
                                                (
                                                    f"(in row {len(array_chunk):d}, "
                                                    f"col '{fields[i].ID}')"
                                                ),
                                            )
                                except Exception as e:
                                    if invalid == "exception":
                                        vo_reraise(e, config, pos)
