    def _parse_fits(self, iterator, extnum, config):
        for start, tag, data, pos in iterator:
            if tag == "STREAM":
                if start:
                    warn_unknown_attrs(
                        "STREAM",
                        data.keys(),
                        config,
                        pos,
                        ["type", "href", "actuate", "encoding", "expires", "rights"],
                    )
                    href = data["href"]
                    encoding = data.get("encoding", None)
                else:
                    break

        if not href.startswith(("http", "ftp", "file")):
            vo_raise(
                NotImplementedError,
                "The vo package only supports remote data through http, ftp or file",
                self._config,
                self._pos,
            )

        fd = urllib.request.urlopen(href)
        if encoding is not None:
            if encoding == "gzip":
                fd = gzip.GzipFile(href, "r", fileobj=fd)
            elif encoding == "base64":
                fd = codecs.EncodedFile(fd, "base64")
            else:
                vo_raise(
                    NotImplementedError,
                    f"Unknown encoding type '{encoding}'",
                    self._config,
                    self._pos,
                )
        hdulist = fits.open(fd)

        array = hdulist[int(extnum)].data
        if array.dtype != self.array.dtype:
            warn_or_raise(W19, W19, (), self._config, self._pos)

        return array

    def _parse_parquet(self, iterator, config):
        """
        Functionality to parse parquet files that are embedded
        in VOTables.
        """
        from astropy.table import Table

        for start, tag, data, pos in iterator:
            if tag == "STREAM":
                if start:
                    warn_unknown_attrs(
                        "STREAM",
                        data.keys(),
                        config,
                        pos,
                        ["type", "href", "actuate", "encoding", "expires", "rights"],
                    )
                    href = data["href"]
                    encoding = data.get("encoding", None)
                else:
                    break

            else:  # in this case, there is no STREAM, hence no file linked.
                href = ""

        if not href.startswith(("http", "ftp", "file")):
            vo_raise(
                NotImplementedError,
                "The vo package only supports remote data through http, ftp or file",
                self._config,
                self._pos,
            )

        try:
            # Hack to keep windows working
            try:
                fd = urllib.request.urlopen(href)
            except urllib.error.URLError:
                # Hack to keep windows working
                if href.startswith("file://"):
                    fd = urllib.request.urlopen(f"file:{href[7:]}")
                # Relative path to parquet part should be relative from the votable
                elif href.startswith("file:"):
                    parquet = os.path.join(
                        os.path.dirname(config["filename"]), href[5:]
                    )
                    fd = urllib.request.urlopen(f"file:{parquet}")

            if encoding is not None:
                if encoding == "gzip":
                    fd = gzip.GzipFile(href, "r", fileobj=fd)
                elif encoding == "base64":
                    fd = codecs.EncodedFile(fd, "base64")
                else:
                    vo_raise(
                        NotImplementedError,
                        f"Unknown encoding type '{encoding}'",
                        self._config,
                        self._pos,
                    )

            array = Table.read(fd, format="parquet")
        finally:
            if hasattr(fd, "close"):
                fd.close()

        if array.dtype != self.array.dtype:
            warn_or_raise(W56, W56, (), self._config, self._pos)

        return array

    def to_xml(self, w, **kwargs):
        specified_format = kwargs.get("tabledata_format")
        if specified_format is not None:
            format = specified_format
        else:
            format = self.format
        if format == "fits":
            format = "tabledata"

        with w.tag(
            "TABLE",
            attrib=w.object_attrs(self, ("ID", "name", "ref", "ucd", "utype", "nrows")),
        ):
            if self.description is not None:
                w.element("DESCRIPTION", self.description, wrap=True)

            for element_set in (self.fields, self.params):
                for element in element_set:
                    element._setup({}, None)

            if self.ref is None:
                for element_set in (self.fields, self.params, self.groups, self.links):
                    for element in element_set:
                        element.to_xml(w, **kwargs)
            elif kwargs["version_1_2_or_later"]:
                index = list(self._votable.iter_tables()).index(self)
                group = Group(self, ID=f"_g{index}")
                group.to_xml(w, **kwargs)

            if len(self.array):
                with w.tag("DATA"):
                    if format == "tabledata":
                        self._write_tabledata(w, **kwargs)
                    elif format == "binary":
                        self._write_binary(1, w, **kwargs)
                    elif format == "binary2":
                        self._write_binary(2, w, **kwargs)

            if kwargs["version_1_2_or_later"]:
                for element in self._infos:
                    element.to_xml(w, **kwargs)

