def bitarray_to_bool(data, length):
    """Unpack a VOTable bit array, whose first bit is the high bit."""
    packed = np.frombuffer(data, dtype=np.uint8)
    return np.unpackbits(packed, bitorder="big")[:length].astype(bool)


